    <script>function reservationPage(){return{showNew:@js($errors->any()&&!old('reservation_id')),showEdit:@js($errors->any()&&old('reservation_id')),view:'today',isDesktop:window.innerWidth>=768,editing:{},init(){window.addEventListener('resize',()=>this.isDesktop=window.innerWidth>=768)},edit(res){this.editing={...res,reservation_time:String(res.reservation_time).replace(' ','T').substring(0,16),restaurant_table_id:res.restaurant_table_id||''};this.showEdit=true},updateUrl(){return @js(route('reservations.update',['reservation'=>'__ID__'])).replace('__ID__',this.editing.id||'')},deleteUrl(){return @js(route('reservations.destroy',['reservation'=>'__ID__'])).replace('__ID__',this.editing.id||'')}}}</script>
